        In1: TryFrom<Self::In>,
        Self::Out: From<Out1>,
    { MappedConnector::new(self) }

    fn boxed(self) -> BoxedConnector<Self::In, Self::Out>
    where
        Self: BoxableConnector<Self::In, Self::Out> + Sized + 'static,
    { self::BoxedConnector::new(self) }
}

